import numpy as np 

def solve ():
    A =np .array ([[3 ,7 ],[-1 ,-2 ]],dtype =object )

    def mat_mul (M1 ,M2 ):
        return np .dot (M1 ,M2 )

    def mat_pow (M ,p ):
        res =np .eye (2 ,dtype =object )
        base =M 
        while p >0 :
            if p %2 ==1 :
                res =mat_mul (res ,base )
            base =mat_mul (base ,base )
            p //=2 
        return res 

    A27 =mat_pow (A ,27 )
    A31 =mat_pow (A ,31 )
    A40 =mat_pow (A ,40 )

    ans =A27 +A31 +A40 
